<span class="line"><span style="color:#E1E4E8;">        </span><span style="color:#F97583;">FROM</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">orders</span><span style="color:#E1E4E8;">.</span><span style="color:#79B8FF;">__sable_migrations</span></span>
